import test from"node:test";import assert from"node:assert/strict";
import{evaluateAssuranceGate,verifyReplay,probabilityInvariant,noDuplicateBusinessEffect,modelRegressionDecision,loadPass,validateTestCase}from"../dist/index.js";
test("probability invariant",()=>assert.equal(probabilityInvariant([0,.2,1]),true));
test("probability invariant rejects invalid",()=>assert.equal(probabilityInvariant([1.2]),false));
test("duplicate effect detected",()=>assert.equal(noDuplicateBusinessEffect(["a","a"]),false));
test("replay divergence fails",()=>assert.equal(verifyReplay({replay_id:"r",dataset_version:"d",code_version:"c",config_version:"x",expected_hash:"a",actual_hash:"b",equivalent:false,differences:["decision"]}).pass,false));
test("critical slice regression fails",()=>assert.equal(modelRegressionDecision({check_id:"x",champion_version:"1",candidate_version:"2",dataset_version:"d",brier_delta:-.01,logloss_delta:-.01,ece_delta:0,max_drawdown_delta:0,coverage_delta:0,critical_slice_regression:true}).decision,"FAIL"));
test("load test requires autoscaling",()=>assert.equal(loadPass({test_id:"l",observed_at:"x",peak_rps:100,peak_events_per_second:100,p95_latency_ms:50,p99_latency_ms:90,error_rate:0,max_queue_age_seconds:1,autoscaling_worked:false,load_shedding_worked:true},{p95:100,p99:150,error:.01,queueAge:5}),false));
test("untraceable test rejected",()=>assert.equal(validateTestCase({test_id:"t",layer:"UNIT",name:"x",owner:"team",critical:false,requirement_refs:[],invariant_refs:[],deterministic:true})[0].code,"UNTRACEABLE_TEST"));
test("clean assurance gate promotes",()=>{const c={snapshot_id:"c",observed_at:"x",requirement_total:10,requirement_covered:10,critical_invariant_total:5,critical_invariant_covered:5,contract_total:3,contract_verified:3};const r=evaluateAssuranceGate({release_id:"r",results:[],coverage:c,unresolved_security_failures:0,critical_data_quality_failures:0,model_regression:null,replay_verified:true,load_verified:true,chaos_verified:true},"x");assert.equal(r.decision,"PROMOTE")});
test("security failure blocks",()=>{const c={snapshot_id:"c",observed_at:"x",requirement_total:10,requirement_covered:10,critical_invariant_total:5,critical_invariant_covered:5,contract_total:3,contract_verified:3};const r=evaluateAssuranceGate({release_id:"r",results:[],coverage:c,unresolved_security_failures:1,critical_data_quality_failures:0,model_regression:null,replay_verified:true,load_verified:true,chaos_verified:true},"x");assert.equal(r.decision,"BLOCK")});
test("critical failed test blocks assurance",()=>{const c={snapshot_id:"c",observed_at:"x",requirement_total:1,requirement_covered:1,critical_invariant_total:1,critical_invariant_covered:1,contract_total:1,contract_verified:1};const tr={run_id:"run",test_id:"critical",layer:"END_TO_END",started_at:"2026-01-01T00:00:00Z",completed_at:"2026-01-01T00:00:01Z",status:"FAIL",critical:true,duration_ms:1,failure_code:"E2E_FAIL",artifact_refs:[],environment:"TEST",source_commit:"abc",immutable:true};const r=evaluateAssuranceGate({release_id:"r",results:[tr],coverage:c,unresolved_security_failures:0,critical_data_quality_failures:0,model_regression:null,replay_verified:true,load_verified:true,chaos_verified:true},"x");assert.equal(r.decision,"BLOCK");assert.equal(r.reason_codes.includes("CRITICAL_TEST_NOT_PASSING"),true)});
